"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def ADD_MATRICES(matrix1, matrix2):
    result = []
    for i in range(0, len(matrix1)):
        row = []
        for j in range(0, len(matrix1[0])):
            row.append((matrix1[i][j] + matrix2[i][j]))
        result.append(row)
    return result
